<section class="store-hero <?= $store['banner_path']?'has-banner':'' ?>" <?= $store['banner_path']?'style="background-image:url(\''.e($store['banner_path']).'\')"':'' ?>><div><p class="store-kicker">Browse · Choose · Order on WhatsApp</p><h1><?= e($store['name']) ?></h1><p><?= e($store['description']?:'A clean catalog built for quick mobile shopping.') ?></p></div><div class="hero-mark" aria-hidden="true"><?= e(mb_strtoupper(mb_substr($store['name'],0,2))) ?></div></section>
<form class="store-search" action="/<?= e($store['slug']) ?>" method="get"><label><span class="search-icon" aria-hidden="true">⌕</span><span class="sr-only">Search products</span><input type="search" name="q" value="<?= e($query) ?>" placeholder="Search products, categories or SKU" autocomplete="off"></label><?php if($selectedCategory):?><input type="hidden" name="category" value="<?= e($selectedCategory['slug']) ?>"><?php endif ?><button type="submit">Search</button></form>
<?php if($categories):?><nav class="store-categories" aria-label="Product categories"><a href="/<?= e($store['slug']) ?>" class="<?= !$selectedCategory?'active':'' ?>">All</a><?php foreach($categories as$category):?><a href="/<?= e($store['slug']) ?>?category=<?= e($category['slug']) ?>" class="<?= $selectedCategory&&$selectedCategory['id']===$category['id']?'active':'' ?>"><?php if($category['image_path']):?><img src="<?= e($category['image_path']) ?>" alt="" loading="lazy"><?php endif ?><span><?= e($category['name']) ?></span><small><?= e($category['product_count']) ?></small></a><?php endforeach ?></nav><?php endif ?>
<?php if($featured):?><section class="store-section"><div class="section-title"><div><span>Curated for you</span><h2>Featured products</h2></div></div><div class="shop-grid featured-grid"><?php foreach($featured as$item)require BASE_PATH.'/resources/views/storefront/partials/product_card.php';?></div></section><?php endif ?>
<section class="store-section"><div class="section-title"><div><span><?= $selectedCategory?'Category':'Catalog' ?></span><h2><?= $query!==''?'Results for “'.e($query).'”':($selectedCategory?e($selectedCategory['name']):'All products') ?></h2></div><small><?= e($catalog['total']) ?> items</small></div><?php if(!$catalog['items']):?><div class="store-empty"><div aria-hidden="true">⌕</div><h3>No products found</h3><p>Try a different search or browse another category.</p><a href="/<?= e($store['slug']) ?>">View all products</a></div><?php else:?><div class="shop-grid"><?php foreach($catalog['items']as$item)require BASE_PATH.'/resources/views/storefront/partials/product_card.php';?></div><?php if($catalog['pages']>1):?><?php $params=[];if($query!=='')$params['q']=$query;if($selectedCategory)$params['category']=$selectedCategory['slug'];?><nav class="store-pagination" aria-label="Catalog pages"><?php if($catalog['page']>1):?><a href="/<?= e($store['slug']) ?>?<?= e(http_build_query($params+['page'=>$catalog['page']-1])) ?>">← Previous</a><?php endif ?><span><?= e($catalog['page']) ?> / <?= e($catalog['pages']) ?></span><?php if($catalog['page']<$catalog['pages']):?><a href="/<?= e($store['slug']) ?>?<?= e(http_build_query($params+['page'=>$catalog['page']+1])) ?>">Next →</a><?php endif ?></nav><?php endif ?><?php endif ?></section>
